SELECT CASE WHEN cost >= 790 THEN 'high' WHEN cost >= 220 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(price) AS total_price, COUNT(*) AS cnt, ROUND(SUM(price) * 100.0 / SUM(SUM(price)) OVER (), 2) AS pct_of_total FROM products WHERE product_name LIKE 'Co%' GROUP BY CASE WHEN cost >= 790 THEN 'high' WHEN cost >= 220 THEN 'mid' ELSE 'low' END ORDER BY pct_of_total DESC, cost_bucket LIMIT 3;
